CREATE FUNCTION operations.check_task_dependency_cycle() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE cycle_found boolean; old_task uuid; old_dependency uuid;
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'DEPENDENCY_WRITE_REQUIRES_READ_COMMITTED'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.business_id IS DISTINCT FROM OLD.business_id THEN RAISE EXCEPTION 'IMMUTABLE_BUSINESS'; END IF;
  old_task:=OLD.task_id; old_dependency:=OLD.depends_on_id;
 END IF;
 PERFORM 1 FROM core.business WHERE id=NEW.business_id FOR UPDATE;
 WITH RECURSIVE reachable(id) AS (
  SELECT NEW.depends_on_id
  UNION
  SELECT dep.depends_on_id FROM operations.task_dependency dep JOIN reachable r ON dep.task_id=r.id
   WHERE dep.business_id=NEW.business_id AND NOT (dep.task_id IS NOT DISTINCT FROM old_task AND dep.depends_on_id IS NOT DISTINCT FROM old_dependency)
 ) SELECT EXISTS(SELECT 1 FROM reachable WHERE id=NEW.task_id) INTO cycle_found;
 IF cycle_found THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='TASK_DEPENDENCY_CYCLE'; END IF;
 RETURN NEW;
END $$
